import{_ as l,o as i,c as t,a5 as o}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"总体思路","description":"","frontmatter":{"title":"总体思路","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","常见需求","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第十部分：常见需求/Office转pdf/总体思路.md","filePath":"posts/java快速入门/第十部分：常见需求/Office转pdf/总体思路.md"}'),a={name:"posts/java快速入门/第十部分：常见需求/Office转pdf/总体思路.md"};function r(d,e,p,s,u,n){return i(),t("div",null,[...e[0]||(e[0]=[o('<div><p>一、在packagecom.ms.web.controller.common的CommonController中定义了一个方法，用来处理前端文件上传请求： 在你的 uploadFiles 方法中，控制器对前端发送的多文件上传请求进行了处理。以下是该方法的主要步骤和操作:</p><ol><li>创建一个空的 uploadedFiles 列表，用于存储上传后的文件信息。</li></ol><p>List&lt;FileVo&gt; uploadedFiles = new ArrayList&lt;&gt;();</p><ol start="3"><li>遍历每个上传的文件:</li></ol><p>for (MultipartFile file : files) {</p><ol start="5"><li>调用 UploadUtil.upload 方法上传每个文件，并获取上传后的文件信息。</li></ol><p>FileVo uploadedFile = UploadUtil.upload(file); // 上传文件并获取文件信息</p><ol start="7"><li>创建 FileEntity 对象，以将文件信息保存到数据库。同时还更新了文件的状态dbFile.setConvertedStatus(0);</li></ol><p>FileEntity dbFile = new FileEntity(); dbFile.setFileName(uploadedFile.getFileName()); dbFile.setFilePath(uploadedFile.getFilePath()); dbFile.setFileType(uploadedFile.getFileType()); dbFile.setFileSize(uploadedFile.getFileSize()); dbFile.setDelFlag(uploadedFile.getDelFlag()); dbFile.setConvertedStatus(0); fileService.saveFile(dbFile);</p><ol start="9"><li>在这里我们定义一套file操作相关的service,serviceImpl,mapper/FileMapper和FileMapper.xml，实现这个saveFile方法；</li><li>调用 UploadUtil.pushToConversionQueue 方法，将文件转换任务推送到消息队列或后台任务队列。</li></ol><p>UploadUtil.pushToConversionQueue(dbFile.getId());</p><ol start="12"><li>将上传后的文件信息添加到 uploadedFiles 列表中。</li></ol><p>uploadedFiles.add(uploadedFile);</p><ol start="14"><li>如果在上述步骤中发生异常，则捕获异常并抛出运行时异常。</li></ol><p>} catch (IOException e) { throw new RuntimeException(e); } catch (SchedulerException e) { throw new RuntimeException(e); }</p><ol start="16"><li>返回上传后的文件信息列表。</li></ol><p>return R.ok(uploadedFiles, SUCCESS);</p><p>通过以上步骤，你的 uploadFiles 方法处理了多文件上传请求，保存了文件信息到数据库，并将文件转换任务推送到了消息队列或后台任务队列进行进一步处理。</p><p>二、接下来到了任务队列如何转换这个文件为pdf了，转换后，还要更新我们的files数据表，添加转换后的路径，转换状态和转换失败信息； public void pushToConversionQueue(Long fileId) throws SchedulerException { // 使用Quartz的JobBuilder创建一个新的JobDetail实例。这代表了一个Job的实例。 // 这里指定了Job的实现类为FileConversionJob，并给该Job设置了一个唯一的标识。 JobDetail jobDetail = JobBuilder.newJob(FileConversionJob.class) .withIdentity(&quot;fileConversionJob&quot; + fileId, &quot;fileConversionGroup&quot;) .build(); // 获取Job的数据映射，并将文件ID放入其中。这样，当Job执行时，我们可以从数据映射中获取到这个ID。 jobDetail.getJobDataMap().put(&quot;fileId&quot;, fileId); // 使用Quartz的TriggerBuilder创建一个新的SimpleTrigger实例。 // 这里指定了Trigger的标识，并设置该Trigger立即启动。 // 还设置了Trigger的调度策略，即每10秒重复执行一次，并且无限重复。 SimpleTrigger trigger = TriggerBuilder.newTrigger() .withIdentity(&quot;fileConversionTrigger&quot; + fileId, &quot;fileConversionGroup&quot;) .startNow() .withSchedule(SimpleScheduleBuilder.simpleSchedule() .withIntervalInSeconds(10) .repeatForever()) .build(); // 使用Scheduler（这是Quartz的核心组件）来安排Job的执行。 // 一旦Job被安排，它将根据上面定义的Trigger的策略被执行。 scheduler.scheduleJob(jobDetail, trigger); }</p></div>',1)])])}const g=l(a,[["render",r]]);export{c as __pageData,g as default};
